  path=append(path,name);positions[strings.Join(path,".")]=n.Label.Pos();indexPositions(n.Value,path,positions)
 case *ast.StructLit:
  for _,d:=range n.Elts {indexPositions(d,path,positions)}
 case *ast.ListLit:
  for i,element:=range n.Elts {indexPositions(element,append(path,fmt.Sprint(i)),positions)}
 }
}

func collectErrors(file string,err error,positions map[string]token.Pos) []Error {
 result:=[]Error{}
